data.query:
query Query($where: WorkcenterWhereInput, $orderBy: [WorkcenterOrderByInput!], $first: Int, $after: String) {
  workcenter(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        replenishmentType {
          id
          name
          expiration
          firstIn
          lastIn
          location
          usable
        }
      }
    }
  }
}

query Replenishment($whereWC:WorkcenterWhereInput!,$wherePSP:ProductStrategyProcessWhereInput! ){
  workcenter(where: $whereWC) {
    edges {
      node {
        putAwayLocationId
      }
    }
  },
  productStrategyProcess(where: $wherePSP) {
    edges {
      node {
        putAwayLocationId
      }
    }
  }
}

query Statuses($where:InventoryStatusWhereInput!){
  inventoryStatus(where:$where) {
    edges {
      node {
        id
      }
    }
  }
}

query LocationPriority($where:LocationPriorityListWhereInput!,$orderBy: [LocationPriorityListOrderByInput!], $after: String){
  locationPriorityList(where:$where, orderBy: $orderBy, first:1, after: $after) {
    edges {
      node {
        id
        priority
        locationId
        locationTypeId
        locationGroupId
      }
    }
  }
}

query Location($where:LocationWhereInput!) {
   location(where: $where){
      edges {
        node {
          id
    }
  }
}
}

