data.variablesTransform:
(
  $request := $state.context.REQUEST;
  $description := "Andon Request: " & $request.andonTypeId & " for Workcenter: " & $request.workcenterId;
  $requiredAt := $moment()

  {
    "payload": {
      "create": $request.{
        "quantity": andonTypeId = "Material" ? {
          "value":quantity,
          "unitId": unitId
        } : null,
        "andonTypeId": andonTypeId,
        "workcenterId": workcenterId,
        "workcenterHistoryId": workcenterHistoryId,
        "productStrategyProcessId": productStrategyProcessId,
        "workOrderId":workOrderId,
        "requiredAt": $coalesce([$request.requiredAt,$requiredAt]),
        "description": $coalesce([$request.description,$description]),
        "destinationLocationId": $coalesce([$state.context.REQUEST.destinationLocationId, $state.context.LOCAL.putAwayLocationId]),
        "sourceLocationId": $coalesce([$state.context.REQUEST.sourceLocationId, $state.context.LOCAL.workcenterLocationId]),
        "andonStageId": "New",
        "andonSeverityId": $coalesce([$state.context.REQUEST.andonSeverityId, $state.context.LOCAL.andonSeverityId])
      }
    }
  }
)

